pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // The contract supports IAccessControl and IERC165. Calling supportsInterface
        // on itself with any interfaceId should return true for those interfaces
        // and false for others. The mutant always returns false, so the rule
        // "the contract self-reports support for at least one interface" is broken.
        bool result = c.supportsInterface(interfaceId);
        bytes4 ierc165 = type(IERC165).interfaceId;
        bytes4 iaccess = type(IAccessControl).interfaceId;
        // If the caller is the contract itself and the interfaceId matches what it should support,
        // it must return true. The fuzzer will find that for IAccessControl or IERC165, the reference
        // returns true but the mutant returns false.
        vm.prank(address(c));
        bool fromSelf = c.supportsInterface(interfaceId);
        if (interfaceId == ierc165 || interfaceId == iaccess) {
            assertTrue(result);
            assertTrue(fromSelf);
        }
    }
}

