// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address account) public {
        // Grant the role to account as admin (TIMELOCK_ADMIN_ROLE is its own admin)
        vm.prank(address(this));
        c.grantRole(c.TIMELOCK_ADMIN_ROLE(), address(this));
        vm.prank(address(this));
        c.grantRole(c.getRoleAdmin(role), address(this));
        vm.prank(address(this));
        c.grantRole(role, account);
        require(c.hasRole(role, account), "setup: grant failed");

        // Revoke the role
        vm.prank(address(this));
        c.revokeRole(role, account);

        // After revocation, the account must not have the role
        assertFalse(c.hasRole(role, account));
    }
}

